"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { WildlifePhoto } from "./wildlife-photos";
import { speciesById } from "./species-data";
import { OTTER_QUESTIONS, OTTER_SOURCE, OTTER_PROFILE_SOURCE } from "./otter-lesson-data";
import { currentAttempts, type ActionRecord, type AnswerHandler, type LearningRecord } from "./learning-records";
import { QuestionChallenge } from "./question-challenge";

export function OtterJourney({ records, onAnswer, onAction, onProfile }: {
  records: LearningRecord[]; onAnswer: AnswerHandler; onAction: (actionId: ActionRecord["actionId"], sessionId: string) => Promise<boolean>; onProfile: () => void;
}) {
  const attempts = currentAttempts(records, OTTER_QUESTIONS);
  const [sessionId, setSessionId] = useState(() => attempts.at(-1)?.sessionId || crypto.randomUUID());
  const sample = (phase: "pre" | "post") => [...new Map(attempts.filter((a) => a.sessionId === sessionId && a.phase === phase).map((a) => [a.questionId, a])).values()];
  const before = sample("pre"), after = sample("post");
  const [step, setStep] = useState<"encounter" | "learn" | "review">(() => after.length === 3 ? "review" : before.length === 3 ? "learn" : "encounter");
  const [questionIndex, setQuestionIndex] = useState(() => before.length < 3 ? before.length : after.length < 3 ? after.length : 0);
  const [challengeOpen, setChallengeOpen] = useState(after.length > 0 && after.length < 3);
  const [actionMessage, setActionMessage] = useState("");
  const [savingAction, setSavingAction] = useState(false);
  const otter = speciesById("smooth-coated-otter")!;
  const phase = step === "encounter" ? "pre" : "post";
  const question = OTTER_QUESTIONS.filter((q) => q.id.startsWith(`otter-${phase}-`))[questionIndex];
  const action = async (actionId: ActionRecord["actionId"]) => {
    if (savingAction) return;
    setSavingAction(true);
    try { setActionMessage(await onAction(actionId, sessionId) ? "Action saved." : "Action could not be saved. Try again."); }
    finally { setSavingAction(false); }
  };
  const next = () => {
    if (questionIndex < 2) setQuestionIndex(questionIndex + 1);
    else { setStep(step === "encounter" ? "learn" : "review"); setQuestionIndex(0); setChallengeOpen(false); window.scrollTo({ top: 0 }); }
  };
  return <div className="aq-view aq-otter-journey">
    <div className="aq-page-title"><div><span className="aq-eyebrow">Guided wildlife journey · about 5 minutes</span><h1>An otter by the canal</h1><p>Compare traits, understand its habitat, and choose a responsible response.</p></div></div>
    <ol className="aq-journey-steps" aria-label="Learning journey"><li aria-current={step === "encounter" ? "step" : undefined}>1 · Encounter and compare</li><li aria-current={step === "learn" ? "step" : undefined}>2 · Learn and answer</li><li aria-current={step === "review" ? "step" : undefined}>3 · Review and act</li></ol>
    {step === "encounter" && <><section className="aq-panel"><h2>Give the animal space first</h2><p>Observe quietly. Avoid feeding, following or cornering otters. Keep pets close on a leash.</p><a href={OTTER_SOURCE} target="_blank" rel="noreferrer">AVS otter guidance ↗</a><p>Use this reference photo to compare traits. This lesson does not identify an uploaded photo.</p><div className="aq-profile-media"><WildlifePhoto animal="smooth-coated-otter" /></div></section><section className="aq-panel"><h2>Before learning · {questionIndex + 1} of 3</h2><p>Answer without hints. Feedback appears after each answer.</p><QuestionChallenge key={`${sessionId}-${question.id}`} question={question} onAnswer={onAnswer} context={{ phase, sessionId }} hintsEnabled={false} onNext={next} nextLabel={questionIndex === 2 ? "Read the lesson" : "Next question"} /></section></>}
    {step === "learn" && <><section className="aq-panel"><h2>Three things to notice</h2><div className="aq-info-grid"><article><h3>Recognise</h3><p>Otters have fur, webbed feet and streamlined bodies. Compare several traits before selecting a profile.</p></article><article><h3>Connect</h3><p>Smooth-coated otters mainly eat fish. Waterways and nearby land support their feeding and travel.</p></article><article><h3>Interpret</h3><p>Regular sightings do not establish a secure population. Singapore’s assessment and the global assessment cover different areas.</p></article></div><div className="aq-profile-status"><div><small>Singapore · RDB3, 2024</small><strong>{otter.singaporeStatus}</strong><a href={otter.statusSourceUrl} target="_blank" rel="noreferrer">National source ↗</a></div><div><small>Global · separate assessment</small><strong>{otter.globalStatus}</strong><a href={otter.globalSourceUrl} target="_blank" rel="noreferrer">Global source ↗</a></div></div><p>Watch quietly from a distance. If an otter is injured or trapped, use the AVS contact guidance.</p><p><a href={OTTER_SOURCE} target="_blank" rel="noreferrer">AVS guidance ↗</a> · <a href={OTTER_PROFILE_SOURCE} target="_blank" rel="noreferrer">NParks profile ↗</a></p>{!challengeOpen && <Button onClick={() => setChallengeOpen(true)}>Check what you learned</Button>}</section>{challengeOpen && <section className="aq-panel"><h2>After learning · {questionIndex + 1} of 3</h2><QuestionChallenge key={`${sessionId}-${question.id}`} question={question} onAnswer={onAnswer} context={{ phase, sessionId }} hintsEnabled={false} onNext={next} nextLabel={questionIndex === 2 ? "See my result" : "Next question"} /></section>}</>}
    {step === "review" && <><section className="aq-panel"><h2>What changed?</h2><p className="aq-journey-score">{before.filter((a) => a.correct).length}/3 before → {after.filter((a) => a.correct).length}/3 after</p><ul>{after.map((a) => <li key={a.id}>{a.objective}: {a.correct ? "answered correctly after learning" : "needs another review"}</li>)}</ul><p>These paired questions measure this session. Feedback also supports learning. This is not proof of lasting knowledge.</p><p>Guided checks do not award XP. Your result is saved with your learning records.</p><Button variant="outline" onClick={() => { setSessionId(crypto.randomUUID()); setStep("encounter"); setQuestionIndex(0); setChallengeOpen(false); }}>Try a new session</Button></section><section className="aq-panel"><h2>Choose your next action</h2><p>You can read guidance now. Report an observation action only if you have actually completed it.</p><a href={OTTER_SOURCE} target="_blank" rel="noreferrer" onClick={() => void action("guidance")}>Open AVS viewing and contact guidance ↗</a><p>Opening guidance does not submit a sighting or contact AVS.</p><Button variant="outline" disabled={savingAction || records.some((r) => r.kind === "action" && r.sessionId === sessionId && r.actionId === "observation")} onClick={() => void action("observation")}>I observed from a distance without feeding</Button><p>Observation completion is reported by you, not independently verified.</p><p role="status">{actionMessage}</p><Button onClick={onProfile}>Explore the full otter profile</Button></section></>}
  </div>;
}

function LearnView({ progress, onComplete, user, signInPath, saveMessage, rewardXp, localMode }: { progress: ProgressState; onComplete: () => void; user: User; signInPath: string; saveMessage: string; rewardXp: number; localMode: boolean }) {
  const complete = progress.completedLessons.includes("rainforest-01");
  const forestLayers = [
    ["Emergent layer", "The tallest crowns receive strong sunlight and wind. Large birds and flying animals can move above the main canopy."],
    ["Canopy", "A dense roof of leaves holds much of a rainforest’s food, shelter and animal activity."],
    ["Understory", "Lower light favours broad leaves. Camouflage and careful movement help animals avoid detection."],
    ["Forest floor", "Fungi, insects and other decomposers recycle fallen material into nutrients."],
  ];
  const adaptations = [
    ["Sunda colugo", "Patagium", "A wide skin membrane creates lift during a controlled glide."],
    ["Oriental pied hornbill", "Large bill", "The bill helps the bird reach, pick up and position fruit."],
    ["Malayan water monitor", "Swimming tail", "This strong swimmer has a long tail that is flattened towards the tip."],
    ["Plantain squirrel", "Gripping claws", "Strong claws help it climb trunks and move among branches in parks and forests."],
  ];
  return (
    <div className="aq-view aq-two-column">
      <div className="aq-page-title"><div><span className="aq-eyebrow">🌿 Guided lesson</span><h1>Singapore rainforest adaptations</h1></div><span className="aq-source-chip"><ShieldCheck /> NParks-linked lesson</span></div>
      <div className="aq-main-column">
        <Panel className="aq-lesson-cover"><WildlifePhoto animal="colugo" /><div><span className="aq-kicker">Lesson 1 · About 8 minutes</span><h2>Life between forest layers</h2><p>Singapore’s rainforests contain several vertical layers. Light, moisture, food and shelter differ from the treetops to the ground, so local animals use different body shapes and behaviours in each layer.</p><div className="aq-lesson-goals"><strong>By the end, you can:</strong><span>name four forest layers</span><span>connect a Singapore animal’s adaptation to its function</span><span>explain one food-web link</span></div></div></Panel>
        <Panel><SectionHead title="Three ideas to remember" /><div className="aq-concept-grid"><article><span>🌿</span><h3>Structure</h3><p>The canopy, understory and forest floor provide different resources.</p></article><article><span>🦎</span><h3>Adaptation</h3><p>Grip, camouflage and gliding help animals use these spaces.</p></article><article><span>🕸️</span><h3>Connection</h3><p>Each species forms part of a larger food web.</p></article></div></Panel>
        <Panel><SectionHead title="The forest from top to bottom" /><div className="aq-detail-list">{forestLayers.map(([name, text], index) => <article key={name}><span>{index + 1}</span><div><h3>{name}</h3><p>{text}</p></div></article>)}</div></Panel>
        <Panel><SectionHead title="Adaptation examples" /><div className="aq-info-grid">{adaptations.map(([animal, feature, text]) => <article key={animal}><span>{animal}</span><h3>{feature}</h3><p>{text}</p></article>)}</div></Panel>
      </div>
      <aside className="aq-side-column">
        <Panel><SectionHead title="Lesson progress" /><Progress value={complete ? 100 : 0} /><p className="aq-muted">{complete ? `Completed · ${rewardXp} XP earned` : "Ready to begin · 8 minutes"}</p><Button onClick={onComplete} disabled={complete}>{complete ? "Lesson complete" : `Complete lesson · +${rewardXp} XP`}</Button>{!user && !localMode && <Button asChild variant="outline"><a href={signInPath} target="_top"><LogIn /> Sign in before saving</a></Button>}<small className="aq-save-state" role="status">{saveMessage}</small></Panel>
        <Panel><SectionHead title="Planned lessons" /><div className="aq-planned-lessons"><p>Movement in trees</p><p>Finding food</p><p>Build a food web</p></div><small className="aq-muted">These lessons are not available yet.</small></Panel>
        <Panel><SectionHead title="Key terms" /><dl className="aq-glossary"><div><dt>Adaptation</dt><dd>A feature or behaviour that improves survival or reproduction in an environment.</dd></div><div><dt>Patagium</dt><dd>A skin membrane used for gliding in animals such as colugos.</dd></div><div><dt>Decomposer</dt><dd>An organism that breaks down dead material and returns nutrients to the ecosystem.</dd></div></dl></Panel>
        <Panel><SectionHead title="Lesson sources" /><p className="aq-compact-copy">These NParks records support the animal examples. Forest layers are a simplified learning model, not fixed boundaries.</p><div className="aq-source-list"><a href="https://biodiversitysg.nparks.gov.sg/our-biodiversity/mammals/other-mammals/sunda-colugo/" target="_blank" rel="noreferrer">Sunda colugo <ExternalLink /></a><a href="https://biodiversitysg.nparks.gov.sg/our-biodiversity/birds/other-birds/oriental-pied-hornbill/" target="_blank" rel="noreferrer">Oriental pied hornbill <ExternalLink /></a><a href="https://www.nparks.gov.sg/visit/parks/park-detail/lower-peirce-reservoir-park/" target="_blank" rel="noreferrer">Water monitor at Lower Peirce <ExternalLink /></a><a href="https://biodiversitysg.nparks.gov.sg/our-biodiversity/mammals/other-mammals/plantain-squirrel/" target="_blank" rel="noreferrer">Plantain squirrel <ExternalLink /></a><a href="https://www.nparks.gov.sg/sbg/research/publications/-/media/sbg/gardenwise/1997-jul-gardenwise-vol-09.pdf" target="_blank" rel="noreferrer">Forest structure · Gardenwise PDF <ExternalLink /></a></div></Panel>
      </aside>
    </div>
  );
}
